create or replace function private.divine_roll(h jsonb,stage integer,attempt integer) returns jsonb language plpgsql volatile set search_path='' as $$
declare rate numeric:=case when attempt<=50 then 1 when attempt<=75 then .5 else .1 end;realm integer:=ceil(stage/2.0);main_keys text[]:=array['mainlineMaterial_xuansi','mainlineMaterial_xuanjuan','mainlineMaterial_xuanpi','mainlineMaterial_lingpi','mainlineMaterial_fengpi','mainlineMaterial_lingyu','mainlineMaterial_lingjing'];herb_keys text[]:=array['craftHerbChiyuan','craftHerbXueyu','craftHerbJinjia','craftHerbQingling'];bag_low integer[][]:=array[[20,15,10,15],[25,20,12,20],[35,25,16,25],[40,30,18,30],[55,35,22,35],[65,40,26,40],[80,50,32,50],[95,55,36,55],[115,65,42,65],[135,75,48,75],[160,90,56,90],[185,100,64,100],[215,115,74,115],[245,130,84,130],[285,150,96,150],[325,170,108,170],[370,195,122,195],[420,220,140,220]];bag_high integer[][]:=array[[40,30,20,30],[50,35,24,35],[65,45,30,45],[75,50,34,50],[95,60,40,60],[110,70,46,70],[135,85,55,85],[155,95,62,95],[185,110,72,110],[215,125,82,125],[250,145,95,145],[285,165,108,165],[325,185,122,185],[365,205,138,205],[420,235,158,235],[470,260,180,260],[530,295,205,295],[600,330,230,330]];b integer[];
begin h:=private.divine_add(h,main_keys[1+floor(random()*7)::integer],1);if stage%2=1 and random()<.35*rate then h:=private.divine_add(h,main_keys[1+floor(random()*7)::integer],1);end if;if random()<(case when stage%2=0 then .75 else .3 end)*rate then h:=private.divine_add(h,'forgeTierMaterial_'||realm,1);end if;if random()<(case when stage%2=0 then .4 else .55 end)*rate then h:=private.divine_add(h,herb_keys[1+floor(random()*4)::integer],1);end if;if random()<(case when stage=18 then .7 when stage%2=0 then .6 else .3 end)*rate then h:=private.divine_add(h,'craftCinnabar',1);end if;h:=private.divine_add(h,'tribPill'||realm,1+floor(random()*2)::integer);if stage%2=0 then b:=array[bag_high[stage][1],bag_high[stage][2],bag_high[stage][3],bag_high[stage][4]];else b:=array[bag_low[stage][1],bag_low[stage][2],bag_low[stage][3],bag_low[stage][4]];end if;h:=private.divine_add(h,'mainlineSpiritStoneBag',floor((b[1]+random())*3)::integer);if random()<.75*rate then h:=private.divine_add(h,'mainlineWoodBag',b[2]);end if;if random()<.6*rate then h:=private.divine_add(h,'mainlineIronBag',b[3]);end if;if random()<.75*rate then h:=private.divine_add(h,'mainlineFoodBag',b[4]);end if;return h;end $$;
revoke all on function private.divine_roll(jsonb,integer,integer) from public,anon,authenticated;
